/**
 * Precompute a map of parent session key → child session keys.
 * Builds in O(n) once; each lookup is O(1).
 * Does NOT include subagent-run children (those require separate registry lookup).
 */
function precomputeChildSessionsByParent(
  store: Record<string, SessionEntry>,
): Map<string, Set<string>> {
  const byParent = new Map<string, Set<string>>();
  for (const [key, entry] of Object.entries(store)) {
    if (!entry) continue;
    const parentKey = entry.parentSessionKey?.trim();
    const spawnedBy = entry.spawnedBy?.trim();
    // A session's parent is the session that spawned it or explicitly set parentSessionKey.
    // Collect both directions: this session as a child of its parent,
    // and this session's children (sessions it spawned / set as parent).
    if (parentKey) {
      if (!byParent.has(parentKey)) byParent.set(parentKey, new Set());
      byParent.get(parentKey)!.add(key);
    }
    if (spawnedBy && spawnedBy !== parentKey) {
      if (!byParent.has(spawnedBy)) byParent.set(spawnedBy, new Set());
      byParent.get(spawnedBy)!.add(key);
    }
  }
  return byParent;
}

