    listSubagentRunsForController(controllerSessionKey)
      .map((entry) => entry.childSessionKey)
      .filter((value) => typeof value === "string" && value.trim().length > 0),
  );
  // Use precomputed map if available (O(1) lookup), otherwise fall back to O(n) scan.
  if (childSessionsByParent) {
    const precomputed = childSessionsByParent.get(controllerSessionKey);
    if (precomputed) {
