      if (spawnedBy === controllerSessionKey || parentSessionKey === controllerSessionKey) {
        childSessionKeys.add(key);
      }
    }
  }
  const childSessions = Array.from(childSessionKeys);
  return childSessions.length > 0 ? childSessions : undefined;
